Given an array of strings arr[] representing an infix expression, we have to evaluate it. An infix expression is of the form "operand1 operator operand2" (e.g., "a + b"), where the operator is written between the two operands.Note: Infix expressions follow precedence: ^ (highest, right-to-left), then * and /, and finally + and - (left-to-right). Division / uses floor division.Examples:Input: arr[] = ["100", "+", "200", "/", "2", "*", "5", "+", "7"] Output: 607Explanation: The expression can be directly read as: (100 + 200 / 2 * 5 + 7). Now, evaluate step by step:200 / 2 = 100100 * 5 = 500500 + 100 = 600600 + 7 = 607Final Answer: 607Input: arr[] = ["2", "^", "3", "^", "2"]Output: 512Explanation: ^ is right-associative → 2 ^ (3 ^ 2) = 2 ^ 9 = 512.Final Answer: 512Try It Yourself[Approach] Using Stack - O(n) Time and O(n) SpaceTo evaluate an infix expression, we must respect operator precedence and associativity. If we try to calculate directly from left to right, the result may be wrong because * and / should come before + and -.The idea is to use two stacks: one stack to store operands (numbers) and another to store operators. By processing the expression from left to right and applying operators in the correct order, we ensure the evaluation follows precedence and associativity rules.How Expression is Evaluated?Traverse the expression from left to right.If it’s an operand, push it onto the operand stack.If it’s an operator, compare its precedence (and associativity) with the operator on top of the stack:If the new operator has higher precedence, or same precedence but is right-associative, push it.Otherwise, apply the operator from the stack on the top two operands until the condition is satisfied, then push the new operator.After scanning the whole expression, apply the remaining operators on the stack to the operands stack to get the result.
            C++

    #include <iostream>
#include <stack>
#include <vector>
#include <cmath>
using namespace std;

// Function to perform calculation on two numbers
int applyOperation(int a, int b, string op) {
    if (op == "+") return a + b;
    if (op == "-") return a - b;
    if (op == "*") return a * b;

    if (op == "/") {
        if (a * b < 0 && a % b != 0)
            return (a / b) - 1;
        return a / b;
    }

    if (op == "^") return pow(a, b);
    return 0;
}

// Function to return precedence of operators
int precedence(string op) {
    if (op == "+" || op == "-") return 1;
    if (op == "*" || op == "/") return 2;
    if (op == "^") return 3;
    return 0;
}

// Function to check if operator is right-associative
bool isRightAssociative(string op) {
    return (op == "^");
}

bool isNumber(string& token) {
    if (token.empty()) return false;
    int start = (token[0] == '-') ? 1 : 0;
    if (start == 1 && token.size() == 1) return false;
    for (int i = start; i < token.size(); i++) {
        if (!isdigit(token[i])) return false;
    }
    return true;
}

// Function to evaluate infix expression
int evaluateInfix(vector<string>& arr) {
    stack<int> values;     
    stack<string> ops;     

    int n = arr.size();
    for (int i = 0; i < n; i++) {
        string token = arr[i];

        // If it's a number, push to values stack
        if (isNumber(token)) {
            values.push(stoi(token));
        }

        // If it's an operator
        else {
            while (!ops.empty() && 
                   ((precedence(ops.top()) > precedence(token)) ||
                   (precedence(ops.top()) == precedence(token) &&
                                    !isRightAssociative(token)))) {

                int val2 = values.top(); values.pop();
                int val1 = values.top(); values.pop();

                string op = ops.top(); ops.pop();

                values.push(applyOperation(val1, val2, op));
            }
            ops.push(token);
        }
    }

    // Process remaining operators
    while (!ops.empty()) {
        int val2 = values.top(); values.pop();
        int val1 = values.top(); values.pop();

        string op = ops.top(); ops.pop();
        values.push(applyOperation(val1, val2, op));
    }

    return values.top();
}

int main() {
    vector<string> arr = {"100", "+", "200", "/", "2", "*", "5", "+", "7"};
    cout << evaluateInfix(arr) << endl; 

    return 0;
}


            C

    #include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <stdbool.h>
#include <ctype.h>

#define MAX 100

// Stack for integers
typedef struct {
    int top;
    unsigned capacity;
    int* array;
} Stack;

// Stack for operators (strings)
typedef struct {
    int top;
    unsigned capacity;
    char* array;
} StringStack;

// Function to perform calculation on two numbers
int applyOperation(int a, int b, char* op) {
    if (strcmp(op, "+") == 0) return a + b;
    if (strcmp(op, "-") == 0) return a - b;
    if (strcmp(op, "*") == 0) return a * b;

    // Floor Division
    if (strcmp(op, "/") == 0) {
        if (a * b < 0 && a % b != 0)
            return (a / b) - 1;
        return a / b;
    }

    if (strcmp(op, "^") == 0) return (int)pow(a, b);
    return 0;
}

// Function to return precedence of operators
int precedence(char* op) {
    if (strcmp(op, "+") == 0 || strcmp(op, "-") == 0) return 1;
    if (strcmp(op, "*") == 0 || strcmp(op, "/") == 0) return 2;
    if (strcmp(op, "^") == 0) return 3;
    return 0;
}

// Function to check if operator is right-associative
bool isRightAssociative(char* op) {
    return (strcmp(op, "^") == 0);
}

// Function to check if token is a number
bool isNumber(char* token) {
    if (token == NULL || *token == '\0') return false;
    int start = (token[0] == '-') ? 1 : 0;
    if (start == 1 && strlen(token) == 1) return false;
    for (int i = start; token[i] != '\0'; i++) {
        if (!isdigit((unsigned char)token[i])) return false;
    }
    return true;
}

// Create stack for values
Stack* createStack(unsigned capacity) {
    Stack* stack = (Stack*)malloc(sizeof(Stack));
    stack->top = -1;
    stack->capacity = capacity;
    stack->array = (int*)malloc(stack->capacity * sizeof(int));
    return stack;
}

// Create stack for operators
StringStack* createStringStack(unsigned capacity) {
    StringStack* stack = (StringStack*)malloc(sizeof(StringStack));
    stack->top = -1;
    stack->capacity = capacity;
    stack->array = (char*)malloc(stack->capacity * sizeof(char) * MAX);
    return stack;
}

// Push integer to stack
void push(Stack* stack, int item) {
    stack->array[++stack->top] = item;
}

// Push operator string to stack
void pushString(StringStack* stack, char* item) {
    strcpy(stack->array + (stack->top + 1) * MAX, item);
    stack->top++;
}

// Pop integer from stack
int pop(Stack* stack) {
    return stack->array[stack->top--];
}

// Pop operator string from stack
char* popString(StringStack* stack) {
    char* item = (char*)malloc(MAX * sizeof(char));
    strcpy(item, stack->array + stack->top * MAX);
    stack->top--;
    return item;
}

// Peek top integer from stack
int peek(Stack* stack) {
    return stack->array[stack->top];
}

// Peek top operator string from stack
char* peekString(StringStack* stack) {
    char* item = (char*)malloc(MAX * sizeof(char));
    strcpy(item, stack->array + stack->top * MAX);
    return item;
}

// Check if integer stack is empty
bool isEmpty(Stack* stack) {
    return stack->top == -1;
}

// Check if operator stack is empty
bool isEmptyString(StringStack* stack) {
    return stack->top == -1;
}

// Function to evaluate infix expression
int evaluateInfix(char** arr, int n) {
    Stack* values = createStack(n);
    StringStack* ops = createStringStack(n);

    for (int i = 0; i < n; i++) {

        // If it's a number, push to values stack
        if (isNumber(arr[i])) {
            push(values, atoi(arr[i]));
        } 

        // If it's an operator
        else {
            while (!isEmptyString(ops) &&
                   (precedence(peekString(ops)) > precedence(arr[i]) ||
                    (precedence(peekString(ops)) == precedence(arr[i])
                                        && !isRightAssociative(arr[i])))) {
                int val2 = pop(values);
                int val1 = pop(values);
                char* op = popString(ops);
                push(values, applyOperation(val1, val2, op));
            }
            pushString(ops, arr[i]);
        }
    }

    // Process remaining operators
    while (!isEmptyString(ops)) {
        int val2 = pop(values);
        int val1 = pop(values);
        char* op = popString(ops);
        push(values, applyOperation(val1, val2, op));
    }

    return peek(values);
}

int main() {
    char* arr[] = {"100", "+", "200", "/", "2", "*", "5", "+", "7"};
    int n = sizeof(arr) / sizeof(arr[0]);

    printf("%d\n", evaluateInfix(arr, n));
    return 0;
}


